const fs = global.get('fs');
const path = global.get('path');
const crypto = global.get('crypto');

if (!fs || !path || !crypto) {
  msg.statusCode = 500;
  msg.payload = {
    error: 'Missing fs/path/crypto in functionGlobalContext. Update Node-RED settings.js before using local auth.'
  };
  return msg;
}

const usersPath = env.get('AUTH_USERS_DB_PATH') || '/var/lib/node-red/auth-users.json';
const sessionsPath = env.get('AUTH_SESSIONS_DB_PATH') || '/var/lib/node-red/auth-sessions.json';
const cookieName = env.get('AUTH_COOKIE_NAME') || 'banksiapark_session';
const cookieDomain = env.get('AUTH_COOKIE_DOMAIN') || '';
const cookieSecure = String(env.get('AUTH_COOKIE_SECURE') || 'false').toLowerCase() === 'true';
const cookieTtlSecondsRaw = Number(env.get('AUTH_SESSION_TTL_SECONDS') || 43200);
const cookieTtlSeconds = Number.isFinite(cookieTtlSecondsRaw) && cookieTtlSecondsRaw > 300 ? Math.round(cookieTtlSecondsRaw) : 43200;
const rememberTtlSecondsRaw = Number(env.get('AUTH_REMEMBER_TTL_SECONDS') || 2592000);
const rememberTtlSeconds = Number.isFinite(rememberTtlSecondsRaw) && rememberTtlSecondsRaw > cookieTtlSeconds ? Math.round(rememberTtlSecondsRaw) : 2592000;
const pbkdf2IterationsRaw = Number(env.get('AUTH_PASSWORD_ITERATIONS') || 210000);
const pbkdf2Iterations = Number.isFinite(pbkdf2IterationsRaw) && pbkdf2IterationsRaw > 10000 ? Math.round(pbkdf2IterationsRaw) : 210000;
const pbkdf2KeyLengthRaw = Number(env.get('AUTH_PASSWORD_KEYLEN') || 64);
const pbkdf2KeyLength = Number.isFinite(pbkdf2KeyLengthRaw) && pbkdf2KeyLengthRaw >= 32 ? Math.round(pbkdf2KeyLengthRaw) : 64;
const nowMs = Date.now();

function readJson(filePath, fallbackValue) {
  try {
    if (!fs.existsSync(filePath)) return fallbackValue;
    const raw = fs.readFileSync(filePath, 'utf8');
    if (!raw || !raw.trim()) return fallbackValue;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' ? parsed : fallbackValue;
  } catch (_error) {
    return fallbackValue;
  }
}

function writeJson(filePath, value) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  fs.writeFileSync(filePath, JSON.stringify(value, null, 2), 'utf8');
}

function parseCookies(req) {
  const cookieHeader = req?.headers?.cookie;
  const out = {};
  String(cookieHeader || '').split(';').forEach((entry) => {
    const index = entry.indexOf('=');
    if (index < 1) return;
    const key = entry.slice(0, index).trim();
    const value = entry.slice(index + 1).trim();
    if (!key) return;
    out[key] = decodeURIComponent(value);
  });
  return out;
}

function roleAliases(role) {
  const normalized = String(role || '').trim().toLowerCase();
  if (normalized === 'administrator') return 'admin';
  if (normalized === 'ops') return 'operator';
  if (normalized === 'view-only') return 'view_only';
  if (normalized === 'view-only-camera') return 'view_only_camera';
  return normalized;
}

function normalizeRoles(value) {
  if (Array.isArray(value)) {
    return Array.from(new Set(value.map(roleAliases).filter(Boolean)));
  }
  const fromString = String(value || '')
    .split(/[\s,;]+/)
    .map((entry) => roleAliases(entry))
    .filter(Boolean);
  return Array.from(new Set(fromString));
}

function buildPermissions(roles) {
  const roleSet = new Set(normalizeRoles(roles));
  const isAdmin = roleSet.has('admin');
  const isOperator = roleSet.has('operator');
  const canViewCameras = isAdmin || isOperator || roleSet.has('view_only_camera');
  const canViewDashboard = isAdmin || isOperator || roleSet.has('view_only') || canViewCameras;
  return {
    admin: isAdmin,
    dashboardView: canViewDashboard,
    cameraView: canViewCameras,
    deviceControl: isAdmin || isOperator
  };
}

function cookieHeaderValue(token, maxAgeSeconds) {
  const segments = [
    `${cookieName}=${encodeURIComponent(token)}`,
    'Path=/',
    'HttpOnly',
    'SameSite=Lax',
    `Max-Age=${Math.max(0, Math.round(maxAgeSeconds || 0))}`
  ];
  if (cookieSecure) segments.push('Secure');
  if (cookieDomain) segments.push(`Domain=${cookieDomain}`);
  return segments.join('; ');
}

function loadUsersDb() {
  const db = readJson(usersPath, { users: [] });
  const users = Array.isArray(db.users) ? db.users : [];
  return { ...db, users };
}

function saveSessionsDb(db) {
  writeJson(sessionsPath, db);
}

function loadSessionsDb() {
  const db = readJson(sessionsPath, { sessions: {} });
  const sessions = db && typeof db.sessions === 'object' && db.sessions ? db.sessions : {};
  return { sessions };
}

function cleanupExpiredSessions(db) {
  const sessions = db.sessions || {};
  Object.keys(sessions).forEach((token) => {
    const expiry = Number(sessions[token]?.expiresAt || 0);
    if (!Number.isFinite(expiry) || expiry <= nowMs) {
      delete sessions[token];
    }
  });
}

function timingSafeEqualHex(leftHex, rightHex) {
  const left = Buffer.from(String(leftHex || ''), 'hex');
  const right = Buffer.from(String(rightHex || ''), 'hex');
  if (left.length === 0 || right.length === 0 || left.length !== right.length) return false;
  return crypto.timingSafeEqual(left, right);
}

function ensureBootstrapUser(db) {
  if (db.users.length > 0) return db;
  const username = String(env.get('AUTH_BOOTSTRAP_ADMIN_USER') || '').trim();
  const password = String(env.get('AUTH_BOOTSTRAP_ADMIN_PASSWORD') || '');
  if (!username || !password) return db;

  const salt = crypto.randomBytes(16).toString('base64url');
  const passwordHash = crypto.pbkdf2Sync(password, salt, pbkdf2Iterations, pbkdf2KeyLength, 'sha512').toString('hex');
  db.users = [{
    username,
    email: null,
    roles: ['admin'],
    enabled: true,
    salt,
    passwordHash,
    iterations: pbkdf2Iterations,
    keyLength: pbkdf2KeyLength,
    digest: 'sha512'
  }];
  writeJson(usersPath, db);
  return db;
}

function findUser(db, username) {
  const normalized = String(username || '').trim().toLowerCase();
  if (!normalized) return null;
  return db.users.find((candidate) => String(candidate?.username || '').trim().toLowerCase() === normalized) || null;
}

function verifyPassword(user, password) {
  const salt = String(user?.salt || '');
  const expectedHash = String(user?.passwordHash || '');
  const iterations = Number(user?.iterations || pbkdf2Iterations);
  const keyLength = Number(user?.keyLength || pbkdf2KeyLength);
  const digest = String(user?.digest || 'sha512');
  if (!salt || !expectedHash) return false;
  const computed = crypto.pbkdf2Sync(String(password || ''), salt, iterations, keyLength, digest).toString('hex');
  return timingSafeEqualHex(computed, expectedHash);
}

function issueSession(user, remember) {
  const sessionsDb = loadSessionsDb();
  cleanupExpiredSessions(sessionsDb);

  const token = crypto.randomBytes(48).toString('base64url');
  const ttlSeconds = remember ? rememberTtlSeconds : cookieTtlSeconds;
  const expiresAt = nowMs + ttlSeconds * 1000;
  const roles = normalizeRoles(user?.roles || user?.role || []);

  sessionsDb.sessions[token] = {
    username: String(user?.username || ''),
    email: user?.email || null,
    roles,
    createdAt: nowMs,
    lastSeenAt: nowMs,
    expiresAt,
    persistent: Boolean(remember),
    ttlSeconds
  };

  saveSessionsDb(sessionsDb);
  return { token, ttlSeconds, session: sessionsDb.sessions[token] };
}

function readCurrentSession() {
  const cookies = parseCookies(msg.req);
  const token = String(cookies[cookieName] || '').trim();
  if (!token) return { token: null, session: null };

  const sessionsDb = loadSessionsDb();
  cleanupExpiredSessions(sessionsDb);
  const session = sessionsDb.sessions[token] || null;
  if (!session) {
    saveSessionsDb(sessionsDb);
    return { token, session: null };
  }

  session.lastSeenAt = nowMs;
  const ttlSeconds = session.persistent && Number(session.ttlSeconds) > cookieTtlSeconds
    ? Number(session.ttlSeconds)
    : cookieTtlSeconds;
  session.expiresAt = nowMs + ttlSeconds * 1000;
  sessionsDb.sessions[token] = session;
  saveSessionsDb(sessionsDb);
  return { token, session };
}

function clearCurrentSession() {
  const cookies = parseCookies(msg.req);
  const token = String(cookies[cookieName] || '').trim();
  if (!token) return;
  const sessionsDb = loadSessionsDb();
  if (sessionsDb.sessions[token]) {
    delete sessionsDb.sessions[token];
    saveSessionsDb(sessionsDb);
  }
}

function authPayload(session) {
  const roles = normalizeRoles(session?.roles || []);
  return {
    authenticated: true,
    user: {
      username: String(session?.username || ''),
      email: session?.email || null
    },
    roles,
    permissions: buildPermissions(roles)
  };
}

const reqPath = String(msg.req?.path || msg.req?.url || '').split('?')[0];
const reqMethod = String(msg.req?.method || msg.method || '').toUpperCase();

if (reqPath === '/api/auth/login' && reqMethod === 'POST') {
  const usersDb = ensureBootstrapUser(loadUsersDb());
  if (!Array.isArray(usersDb.users) || usersDb.users.length === 0) {
    msg.statusCode = 503;
    msg.payload = {
      error: 'No local users configured. Create auth-users.json or set AUTH_BOOTSTRAP_ADMIN_USER and AUTH_BOOTSTRAP_ADMIN_PASSWORD.'
    };
    return msg;
  }

  let body = msg.payload;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (_error) { body = {}; }
  }
  if (!body || typeof body !== 'object') body = {};

  const username = String(body.username || '').trim();
  const password = String(body.password || '');
  if (!username || !password) {
    msg.statusCode = 400;
    msg.payload = { error: 'Username and password are required.' };
    return msg;
  }

  const user = findUser(usersDb, username);
  if (!user || user.enabled === false || !verifyPassword(user, password)) {
    msg.statusCode = 401;
    msg.payload = { error: 'Invalid username or password.' };
    return msg;
  }

  const remember = body.remember === true || body.remember === 'true';
  const issued = issueSession(user, remember);
  msg.headers = msg.headers || {};
  msg.headers['Set-Cookie'] = cookieHeaderValue(issued.token, issued.ttlSeconds);
  msg.statusCode = 200;
  msg.payload = authPayload(issued.session);
  return msg;
}

if (reqPath === '/api/auth/logout' && reqMethod === 'POST') {
  clearCurrentSession();
  msg.headers = msg.headers || {};
  msg.headers['Set-Cookie'] = cookieHeaderValue('', 0);
  msg.statusCode = 200;
  msg.payload = { ok: true };
  return msg;
}

if ((reqPath === '/api/session' && reqMethod === 'GET') || (reqPath === '/api/auth/check' && reqMethod === 'GET')) {
  const current = readCurrentSession();
  if (!current.session) {
    msg.statusCode = 401;
    msg.payload = reqPath === '/api/session'
      ? { authenticated: false, error: 'Authentication required' }
      : { ok: false };
    return msg;
  }

  const payload = authPayload(current.session);
  const canAccessDashboard = Boolean(payload.permissions?.dashboardView);
  if (!canAccessDashboard) {
    msg.statusCode = 403;
    msg.payload = reqPath === '/api/session'
      ? { authenticated: false, error: 'No dashboard role assigned.' }
      : { ok: false };
    return msg;
  }

  msg.statusCode = reqPath === '/api/auth/check' ? 204 : 200;
  msg.payload = reqPath === '/api/auth/check' ? '' : payload;
  return msg;
}

msg.statusCode = 404;
msg.payload = { error: 'Not found' };
return msg;
